script:
// Adds a "Convert (Wizard)" action next to the stock "Convert to Deal" button.
// Shipped by the Pranera CRM app (fixture). Uses the setupForm() contract, which
// leaves other Form Scripts' actions untouched.
function setupForm({ doc }) {
  return {
    actions: doc.converted
      ? []
      : [
          {
            label: 'Convert (Wizard)',
            onClick: () =>
              window.location.assign('/deal_wizard/' + encodeURIComponent(doc.name)),
          },
        ],
  }
}
